const datasets={30:{kpis:[112,19,10.8,98.1],demand:[42,48,55,62,59,71,75],placements:[6,7,8,9,10,11,13],labels:['W1','W2','W3','W4','W5','W6','Now']},90:{kpis:[284,47,12.4,97.2],demand:[36,43,41,53,57,64,61,72,68,76,73,79],placements:[4,5,6,7,7,8,8,10,9,11,12,13],labels:['Sep 1','Sep 15','Oct 1','Oct 15','Nov 1','Nov 15','Dec 1','Dec 15','Jan 1','Jan 15','Feb 1','Now']},365:{kpis:[1168,184,14.1,95.8],demand:[44,48,52,50,57,61,65,63,71,73,76,79],placements:[5,6,7,7,8,8,9,9,10,11,11,13],labels:['Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec','Jan','Feb']}};
const channelData={qualified:[['Search + Maps',108,38],['Shop / walk-in',68,24],['Pet platforms',48,17],['LINE',34,12],['Social',26,9]],conversion:[['Shop / walk-in',26.8,100],['Search + Maps',19.4,72],['Pet platforms',15.8,59],['LINE',12.1,45],['Social',7.6,28]],cost:[['Search + Maps',4200,58],['Shop / walk-in',2800,39],['Pet platforms',5100,71],['LINE',1900,26],['Social',7200,100]]};
const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];let activeRange=90,slide=0,toastTimer;
function formatKpi(v,i){if(i===2)return `${v}<span> days</span>`;if(i===3)return `${v}<span>%</span>`;return Math.round(v).toLocaleString()}
function animateKpis(values){$$('.kpi-value').forEach((el,i)=>{const start=parseFloat(el.dataset.value)||0,end=values[i],t0=performance.now();function tick(t){const p=Math.min((t-t0)/450,1),n=start+(end-start)*(1-Math.pow(1-p,3));el.innerHTML=formatKpi(i<2?Math.round(n):n.toFixed(1),i);if(p<1)requestAnimationFrame(tick);else el.dataset.value=end}requestAnimationFrame(tick)})}
function drawChart(data){const svg=$('#performance-chart svg'),W=645,H=180,x0=55,y0=30,max=80;const pts=arr=>arr.map((v,i)=>[x0+i*(W/(arr.length-1)),y0+(max-v)*(H/max)]);const demand=pts(data.demand),placements=pts(data.placements);const path=p=>p.map((q,i)=>`${i?'L':'M'}${q[0].toFixed(1)},${q[1].toFixed(1)}`).join(' ');$('#demand-line').setAttribute('d',path(demand));$('#placement-line').setAttribute('d',path(placements));$('#demand-area').setAttribute('d',`${path(demand)} L700,210 L55,210 Z`);const points=$('#chart-points');points.innerHTML='';demand.forEach((p,i)=>{const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx',p[0]);c.setAttribute('cy',p[1]);c.setAttribute('r','5');c.setAttribute('fill','#fff');c.setAttribute('stroke','#1f8a8a');c.setAttribute('stroke-width','3');c.classList.add('chart-point');c.addEventListener('mouseenter',e=>showChartTip(e,data,i));c.addEventListener('mouseleave',hideChartTip);points.append(c)});const labels=$('#x-labels');labels.innerHTML='';data.labels.forEach((label,i)=>{if(i%Math.ceil(data.labels.length/6)!==0&&i!==data.labels.length-1)return;const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',x0+i*(W/(data.labels.length-1)));t.setAttribute('y','248');t.setAttribute('text-anchor','middle');t.textContent=label;labels.append(t)})}
function showChartTip(e,data,i){const tip=$('#chart-tooltip'),rect=$('#performance-chart').getBoundingClientRect(),svgRect=$('#performance-chart svg').getBoundingClientRect();const x=(parseFloat(e.target.getAttribute('cx'))/720)*svgRect.width;const y=(parseFloat(e.target.getAttribute('cy'))/280)*svgRect.height;tip.innerHTML=`<strong>${data.labels[i]}</strong><br>${data.demand[i]} qualified · ${data.placements[i]} placed`;tip.style.left=`${x}px`;tip.style.top=`${y}px`;tip.style.opacity=1}function hideChartTip(){$('#chart-tooltip').style.opacity=0}
function renderChannels(metric='qualified'){const root=$('#channel-chart');root.innerHTML='';channelData[metric].forEach(([name,value,width])=>{const label=metric==='conversion'?`${value}%`:metric==='cost'?`¥${value.toLocaleString()}`:value;root.insertAdjacentHTML('beforeend',`<div class="channel-row"><span>${name}</span><div class="bar-track"><i style="width:${width}%"></i></div><strong>${label}</strong></div>`)});}
function setRange(range){activeRange=range;$$('.range-control button').forEach(b=>b.classList.toggle('active',+b.dataset.range===range));animateKpis(datasets[range].kpis);drawChart(datasets[range]);showToast(`Dashboard updated to ${range===365?'12 months':range+' days'}.`)}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function openModal(el){el.hidden=false;document.body.style.overflow='hidden'}function closeModal(el){el.hidden=true;document.body.style.overflow=''}
function showSlide(index){slide=Math.max(0,Math.min(2,index));$$('.slide').forEach((s,i)=>s.classList.toggle('active',i===slide));$('#slide-current').textContent=slide+1;$('#prev-slide').disabled=slide===0;$('#next-slide').textContent=slide===2?'Done':'Next'}
$$('.range-control button').forEach(b=>b.addEventListener('click',()=>setRange(+b.dataset.range)));$('#channel-metric').addEventListener('change',e=>renderChannels(e.target.value));
[$('#board-mode'),$('#board-mode-bottom')].forEach(b=>b.addEventListener('click',()=>{showSlide(0);openModal($('#board-modal'))}));$('#close-board').addEventListener('click',()=>closeModal($('#board-modal')));$('#next-slide').addEventListener('click',()=>slide===2?closeModal($('#board-modal')):showSlide(slide+1));$('#prev-slide').addEventListener('click',()=>showSlide(slide-1));
$('#open-readiness').addEventListener('click',()=>openModal($('#readiness-modal')));$('#close-readiness').addEventListener('click',()=>closeModal($('#readiness-modal')));$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m)}));
$('#export-button').addEventListener('click',()=>{const blob=new Blob([`TOKYO PET PLATFORM — EXECUTIVE BRIEF\n\nIllustrative concept metrics (${activeRange===365?'12 months':activeRange+' days'})\nQualified demand: ${datasets[activeRange].kpis[0]}\nSuccessful placements: ${datasets[activeRange].kpis[1]}\nMedian time to placement: ${datasets[activeRange].kpis[2]} days\nJourney traceability: ${datasets[activeRange].kpis[3]}%\n\nDecision: prove one complete vertical slice from source to post-handover feedback.`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='tokyo-pet-executive-brief.txt';a.click();URL.revokeObjectURL(a.href);showToast('Executive brief exported.')});
$$('[data-toast]').forEach(el=>el.addEventListener('click',()=>showToast(el.dataset.toast)));$('#theme-toggle').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));$('#menu-button').addEventListener('click',e=>{const open=$('#sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});$$('.nav-item').forEach(a=>a.addEventListener('click',()=>{$$('.nav-item').forEach(n=>n.classList.remove('active'));a.classList.add('active');$('#sidebar').classList.remove('open')}));
document.addEventListener('keydown',e=>{if(!$('#board-modal').hidden){if(e.key==='ArrowRight')showSlide(slide+1);if(e.key==='ArrowLeft')showSlide(slide-1);if(e.key==='Escape')closeModal($('#board-modal'))}else if(!$('#readiness-modal').hidden&&e.key==='Escape')closeModal($('#readiness-modal'))});
drawChart(datasets[90]);renderChannels();
